"use client";
import { ReactNode, useEffect } from "react";

type ModalProps = {
  open: boolean;
  onClose: () => void;
  title?: ReactNode;
  children: ReactNode;
  footer?: ReactNode;
  size?: "md" | "lg";
  /** When true, clicking the backdrop / pressing Escape will NOT close (Bootstrap's static backdrop). */
  staticBackdrop?: boolean;
  /** Hide the header close button (e.g. while a request is in-flight). */
  hideClose?: boolean;
};

/**
 * React-state modal that replaces Bootstrap's data-bs-toggle="modal" mechanism.
 * Handles body scroll-lock, backdrop, Escape-to-close and the entrance
 * animation, styled to match the new design system.
 */
export default function Modal({
  open,
  onClose,
  title,
  children,
  footer,
  size = "md",
  staticBackdrop = false,
  hideClose = false,
}: ModalProps) {
  useEffect(() => {
    if (open) document.body.style.overflow = "hidden";
    else document.body.style.overflow = "";
    return () => {
      document.body.style.overflow = "";
    };
  }, [open]);

  useEffect(() => {
    if (!open || staticBackdrop) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, staticBackdrop, onClose]);

  if (!open) return null;

  const maxW = size === "lg" ? "tw-max-w-[820px]" : "tw-max-w-[520px]";

  return (
    <>
      <div
        onClick={staticBackdrop ? undefined : onClose}
        className="tw-fixed tw-inset-0 tw-z-[1050]"
        style={{
          background: "rgba(20,16,28,0.6)",
          backdropFilter: "blur(4px)",
          animation: "tsb-modal-fadein 0.2s ease",
        }}
        aria-hidden="true"
      />
      <div
        role="dialog"
        aria-modal="true"
        className={`tw-fixed tw-left-1/2 tw-top-1/2 tw-w-[92%] ${maxW} tw-z-[1060] tw-flex tw-flex-col tw-bg-white`}
        style={{
          transform: "translate(-50%,-50%)",
          borderRadius: 20,
          boxShadow: "0 24px 60px rgba(20,16,28,0.24)",
          maxHeight: "90vh",
          animation: "tsb-modal-slidein 0.3s cubic-bezier(.5,0,.25,1)",
        }}
      >
        <style>{`@keyframes tsb-modal-fadein{from{opacity:0}to{opacity:1}}@keyframes tsb-modal-slidein{from{opacity:0;transform:translate(-50%,-46%)}to{opacity:1;transform:translate(-50%,-50%)}}`}</style>
        {(title || !hideClose) && (
          <div className="tw-flex tw-items-center tw-justify-between tw-gap-4 tw-px-5 tw-py-4 tw-border-0 tw-border-b tw-border-solid tw-border-[#ebe7f0]">
            <h2 className="tw-font-display tw-text-[18px] tw-font-bold tw-text-[#14101c] tw-m-0">
              {title}
            </h2>
            {!hideClose && (
              <button
                type="button"
                onClick={onClose}
                aria-label="Close"
                className="tw-shrink-0 tw-w-9 tw-h-9 tw-rounded-full tw-grid tw-place-items-center tw-bg-[#faf9fc] tw-text-[#2a2336] tw-text-[20px] tw-leading-none tw-border-0 tw-cursor-pointer hover:tw-bg-[#ebe7f0] hover:tw-text-[#14101c] tw-transition-colors"
              >
                ×
              </button>
            )}
          </div>
        )}
        <div className="tw-px-5 tw-py-4 tw-overflow-y-auto">{children}</div>
        {footer && (
          <div className="tw-flex tw-items-center tw-justify-end tw-gap-2 tw-px-5 tw-py-4 tw-border-0 tw-border-t tw-border-solid tw-border-[#ebe7f0]">
            {footer}
          </div>
        )}
      </div>
    </>
  );
}
